            BACKEND_PENDING_PULL_RECORD = None
            BACKEND_LATEST_PUSH_RECORD = None
            BACKEND_SESSION_ID = None
            BACKEND_ATTEMPT_RECORD = None
            BACKEND_LIFECYCLE = BackendLifecycle.READY
