        os.close(descriptor)
        raise _PushConfigurationError(Locale.REPLAY_LOG_ALREADY_LOCKED) from exc
    AUTHORITATIVE_LOG_DESCRIPTOR = descriptor


def _release_authoritative_process_lock() -> None:
