def _initialize_readme_authoritative_schema(
    conn: duckdb.DuckDBPyConnection,
) -> None:
    conn.execute(CREATE_AUTHORITATIVE_RECORDS_TABLE_SQL)
    conn.execute(CREATE_AUTHORITATIVE_OUTCOMES_TABLE_SQL)
