    @classmethod
    def validate_url(cls, v: AnyUrl | None) -> AnyUrl | None:
        """Validate URL is non-empty and has no fragment."""
        if v is None:
            return None

        url_str = str(v)
        if not url_str or url_str.isspace():
            raise ValueError("URL must be a valid non-empty URL")

        parsed = urlparse(url_str)

