) -> HttpRequestLogRecord:
    pull_ordinal, pull = _projected_http_record(conn, pull_record.record_id)
    if (pull.method, pull.path) != (HTTP_GET_METHOD, PULL_PATH):
        raise _PushValidationError(Locale.REPLAY_COMMIT_PULL_INVALID)
